public async Task<CartExtendedResponse>
Handle(UpdateCartItemQuantityCommand command, CancellationToken
cancellationToken)
{
var cartDetail = await
_repository.GetAsync(command.CartId);
if (command.IsAddOperation)
cartDetail.Items.FirstOrDefault(x => x.CartItemId ==
command.CartItemId)?.IncreaseQuantity();
else
cartDetail.Items.FirstOrDefault(x => x.CartItemId ==
command.CartItemId)?. DecreaseQuantity();
var cartItemsList = cartDetail.Items.ToList();
Service Ecosystem Patterns Chapter 13
[ 312 ]
cartItemsList.RemoveAll(x => x.Quantity <= 0);
cartDetail.Items = cartItemsList;
await _repository.AddOrUpdateAsync(cartDetail);
var response = _mapper.Map<CartExtendedResponse>
(cartDetail);
var tasks = response.Items
.Select(async x => await
_catalogService.EnrichCartItem(x, cancellationToken));
response.Items = await Task.WhenAll(tasks);
return response;
}
}
}
The handler accepts UpdateCartItemQuantityRequest, which defines the CartId,
CartItemId, and a Boolean that denotes whether the request is to increase or decrease the
quantity of the specified item.
The handler uses the same dependencies that the other handlers do and it performs some
additional checks about the removal of the item if the amount is equal to zero. If the
quantity associated with CartItemId reaches 0, then the item is removed from the cart
session; otherwise, the quantity is updated and the cart proceeds by updating the Redis
store and retrieving cartDetail.
